const base = Math.floor(totalCents / ways);
const leftover = totalCents - base * ways;
// The first `leftover` borrowers pay one cent more, so the shares add up to the charge.
return Array.from({ length: ways }, (_, i) => base + (i < leftover ? 1 : 0));
